persuasion_principles:
{
    "Reciprocity": {"Explanation": "The email offers a significant financial benefit (100% match bonus up to $300) in exchange for creating an account and making a deposit, which can be seen as a form of reciprocity."},
    "Scarcity": {"Explanation": "The email does not explicitly mention scarcity, such as limiting the offer to a certain time or number of participants."},
    "Authority": {"Explanation": "The email does not reference any authority figures or credible institutions to lend legitimacy to the offer."},
    "Commitment/Consistency": {"Explanation": "The email does not reference prior behavior or choices to push for further action."},
    "Liking": {"Explanation": "The email does not use familiarity, flattery, or personalization to build trust or rapport."},
    "Social proof": {"Explanation": "The email does not reference other people's participation or endorsements to influence the reader's decision."}
}

