    "Commitment/Consistency": {"Explanation": "Not present. The email does not reference any prior behaviors or choices to push for further action."},
    "Liking": {"Explanation": "Not present. There is no indication of using familiarity, flattery, or personalization to build trust or rapport."},
    "Social proof": {"Explanation": "Not present. The email does not reference any other people's participation or endorsement to influence the recipient's decision."}
}

